/**
 * WebGCS Connection Management
 * Handles SocketIO connection and real-time communication.
 */

class ConnectionManager {
    constructor() {
        this.socket = null;
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = 10;
        this.heartbeatInterval = null;
        this.eventHandlers = new Map();
    }

    /**
     * Initialize connection manager
     */
    initialize() {
        console.log('Initializing connection manager...');
        this.connect();
        this.setupEventHandlers();
    }

    /**
     * Establish SocketIO connection
     */
    connect() {
        if (this.socket && this.socket.connected) {
            console.log('Already connected');
            return;
        }

        console.log('Connecting to WebGCS server...');

        this.socket = io({
            autoConnect: true,
            reconnection: true,
            reconnectionDelay: 2000,
            reconnectionAttempts: this.maxReconnectAttempts,
            transports: ['polling', 'websocket'],  // Try polling first, then websocket
            upgrade: true,  // Allow upgrading to websocket
            timeout: 20000,  // Connection timeout
            forceNew: true   // Force new connection
        });

        // Store socket globally
        window.WebGCS.socket = this.socket;

        console.log('Socket created, initial state:', {
            connected: this.socket.connected,
            disconnected: this.socket.disconnected,
            id: this.socket.id,
            readyState: this.socket.readyState
        });

        this.setupSocketEvents();

        // Force connection if autoConnect didn't work
        if (!this.socket.connected) {
            console.log('Force opening socket connection...');
            this.socket.open();
        }
    }

    /**
     * Setup SocketIO event handlers
     */
    setupSocketEvents() {
        console.log('Setting up SocketIO event handlers...');

        this.socket.on('connect', () => {
            console.log('🟢 SOCKET CONNECTED to WebGCS server! Socket ID:', this.socket.id);
            window.WebGCS.connected = true;
            this.reconnectAttempts = 0;
            this.startHeartbeat();
            this.triggerEvent('connected');
        });

        this.socket.on('disconnect', (reason) => {
            console.log('🔴 SOCKET DISCONNECTED from server:', reason);
            window.WebGCS.connected = false;
            window.WebGCS.droneConnected = false;
            this.stopHeartbeat();
            this.triggerEvent('disconnected', reason);
        });

        this.socket.on('reconnect_attempt', (attemptNumber) => {
            console.log(`Reconnection attempt ${attemptNumber}`);
            this.reconnectAttempts = attemptNumber;
        });

        this.socket.on('drone_connected', (data) => {
            console.log('Drone connected:', data);
            window.WebGCS.droneConnected = true;
            this.triggerEvent('drone_connected', data);
        });

        this.socket.on('drone_disconnected', (data) => {
            console.log('Drone disconnected:', data);
            window.WebGCS.droneConnected = false;
            this.triggerEvent('drone_disconnected', data);
        });

        this.socket.on('telemetry_update', (data) => {
            console.log('Telemetry update received:', data);
            window.WebGCS.telemetryData = { ...window.WebGCS.telemetryData, ...data };

            // Update heartbeat display
            if (data.timestamp || data.connection_status?.last_heartbeat) {
                const timestamp = data.timestamp || data.connection_status.last_heartbeat;
                const heartbeatTime = new Date(timestamp).toLocaleTimeString();
                const lastHeartbeat = document.getElementById('last-heartbeat');
                const telemetryHeartbeat = document.getElementById('telemetry-last-heartbeat');

                if (lastHeartbeat) lastHeartbeat.textContent = heartbeatTime;
                if (telemetryHeartbeat) telemetryHeartbeat.textContent = heartbeatTime;
            }

            // Trigger event for other components
            this.triggerEvent('telemetry_update', data);
        });

        // FIX: Handle system status updates
        this.socket.on('system_status', (data) => {
            console.log('System status update:', data);
            window.WebGCS.droneConnected = data.mavlink_connected;
            window.WebGCS.droneArmed = data.drone_armed;
            window.WebGCS.flightMode = data.flight_mode;

            // Update UI
            this.updateConnectionUI();
        });

        this.socket.on('command_acknowledged', (data) => {
            console.log('Command acknowledged:', data);
            this.triggerEvent('command_acknowledged', data);
        });

        this.socket.on('command_error', (data) => {
            console.error('Command error:', data);
            this.triggerEvent('command_error', data);
        });

        this.socket.on('connection_error', (data) => {
            console.error('Connection error:', data);
            this.triggerEvent('connection_error', data);
        });

        this.socket.on('error', (error) => {
            console.error('🚨 SOCKET ERROR:', error);
            this.triggerEvent('error', error);
        });

        this.socket.on('connect_error', (error) => {
            console.error('🚨 CONNECTION ERROR:', error.message || error);
            this.triggerEvent('connection_error', error);
        });
    }

    /**
     * Setup application event handlers
     */
    setupEventHandlers() {
        // Register for telemetry updates
        this.on('telemetry_update', (data) => {
            if (window.WebGCS.modules.telemetry) {
                window.WebGCS.modules.telemetry.updateDisplay(data);
            }
            if (window.WebGCS.modules.pfd) {
                window.WebGCS.modules.pfd.updateDisplay(data);
            }
        });

        // Register for connection status updates
        this.on('connected', () => {
            this.updateConnectionUI();
        });

        this.on('disconnected', () => {
            this.updateConnectionUI();
        });

        this.on('drone_connected', () => {
            this.updateConnectionUI();
        });

        this.on('drone_disconnected', () => {
            this.updateConnectionUI();
        });
    }

    /**
     * Update connection UI elements
     */
    updateConnectionUI() {
        // Update main connection status
        if (typeof updateConnectionStatus === 'function') {
            updateConnectionStatus();
        }

        // Update drone connection button
        const connectBtn = document.getElementById('connect-drone-btn');
        if (connectBtn) {
            const connected = window.WebGCS.droneConnected;
            connectBtn.textContent = connected ? 'Disconnect' : 'Connect';
            connectBtn.className = `btn ${connected ? 'btn-danger' : 'btn-primary'}`;
        }
    }

    /**
     * Start heartbeat mechanism
     */
    startHeartbeat() {
        this.stopHeartbeat();
        this.heartbeatInterval = setInterval(() => {
            if (this.socket && this.socket.connected) {
                this.socket.emit('heartbeat');
            }
        }, 10000); // 10 second heartbeat
    }

    /**
     * Stop heartbeat mechanism
     */
    stopHeartbeat() {
        if (this.heartbeatInterval) {
            clearInterval(this.heartbeatInterval);
            this.heartbeatInterval = null;
        }
    }

    /**
     * Disconnect from server
     */
    disconnect() {
        console.log('Disconnecting from server...');
        if (this.socket) {
            this.socket.disconnect();
        }
        this.stopHeartbeat();
    }

    /**
     * Send command to drone via SocketIO
     */
    sendCommand(command, params = {}) {
        if (!this.socket || !this.socket.connected) {
            console.error('Cannot send command: not connected to server');
            return false;
        }

        console.log('Sending command:', command, params);

        this.socket.emit('send_command', {
            command: command,
            parameters: params,
            timestamp: Date.now()
        });

        return true;
    }

    /**
     * Register event handler
     */
    on(event, handler) {
        if (!this.eventHandlers.has(event)) {
            this.eventHandlers.set(event, []);
        }
        this.eventHandlers.get(event).push(handler);
    }

    /**
     * Trigger event handlers
     */
    triggerEvent(event, data = null) {
        const handlers = this.eventHandlers.get(event);
        if (handlers) {
            handlers.forEach(handler => {
                try {
                    handler(data);
                } catch (error) {
                    console.error(`Error in ${event} handler:`, error);
                }
            });
        }
    }
}

// Export for use in main.js
window.ConnectionManager = ConnectionManager;

/**
 * WebGCS Flight Controls
 * Handles flight control buttons with safety confirmations.
 */

class FlightControls {
    constructor() {
        this.commandTimeout = 5000;
        this.pendingCommands = new Map();
    }

    /**
     * Initialize flight controls
     */
    initialize() {
        console.log('Initializing flight controls...');
        this.setupEventListeners();
        this.updateButtonStates();
        this.setupSocketEventHandlers();
    }

    /**
     * Setup event listeners for flight control buttons
     */
    setupEventListeners() {
        // Connection controls
        this.bindButton('connect-drone-btn', this.handleConnectDrone.bind(this));

        // ARM/DISARM controls with safety confirmations
        this.bindButton('arm-btn', () => this.handleArmCommand());
        this.bindButton('disarm-btn', () => this.handleDisarmCommand());

        // Flight mode controls
        this.bindButton('stabilize-btn', () => this.handleFlightMode('STABILIZE'));
        this.bindButton('alt-hold-btn', () => this.handleFlightMode('ALT_HOLD'));
        this.bindButton('loiter-btn', () => this.handleFlightMode('LOITER'));
        this.bindButton('guided-btn', () => this.handleFlightMode('GUIDED'));
        this.bindButton('rtl-btn', () => this.handleFlightMode('RTL'));
        this.bindButton('auto-btn', () => this.handleFlightMode('AUTO'));
        this.bindButton('land-btn', () => this.handleFlightMode('LAND'));

        // Takeoff control with safety confirmation
        this.bindButton('takeoff-btn', () => this.handleTakeoffCommand());

        // Emergency controls
        this.bindButton('emergency-stop-btn', () => this.handleEmergencyStop());

        // Navigation controls
        this.bindButton('goto-btn', () => this.handleGotoWaypoint());
        this.bindButton('set-home-btn', () => this.handleSetHome());

        // Gimbal controls
        this.bindButton('gimbal-center-btn', () => this.handleGimbalCenter());
        this.bindButton('gimbal-down-btn', () => this.handleGimbalDown());
    }

    /**
     * Bind button click event with error handling
     */
    bindButton(buttonId, handler) {
        const button = document.getElementById(buttonId);
        if (button) {
            button.addEventListener('click', (event) => {
                event.preventDefault();
                try {
                    handler();
                } catch (error) {
                    console.error(`Error in ${buttonId} handler:`, error);
                }
            });
        }
    }

    /**
     * Handle drone connection toggle
     */
    handleConnectDrone() {
        const connected = window.WebGCS.droneConnected;
        const connectionManager = window.WebGCS.modules.connection;

        if (!connectionManager) {
            console.error('Connection manager not available');
            return;
        }

        if (connected) {
            if (window.WebGCS.utils.showConfirmation('Disconnect from drone?')) {
                connectionManager.sendCommand('disconnect_drone');
            }
        } else {
            connectionManager.sendCommand('connect_drone');
        }
    }

    /**
     * Handle ARM command with safety confirmation
     */
    handleArmCommand() {
        if (!this.validateConnection()) return;

        const message = 'ARM the drone? This will enable motor spinning.';
        if (window.WebGCS.utils.showConfirmation(message)) {
            this.sendCommand('arm', {}, 'Arming drone...');
        }
    }

    /**
     * Handle DISARM command with safety confirmation
     */
    handleDisarmCommand() {
        if (!this.validateConnection()) return;

        const message = 'DISARM the drone? Motors will stop immediately.';
        if (window.WebGCS.utils.showConfirmation(message)) {
            this.sendCommand('disarm', {}, 'Disarming drone...');
        }
    }

    /**
     * Handle flight mode change
     */
    handleFlightMode(mode) {
        if (!this.validateConnection()) return;

        this.sendCommand('set_mode', { mode: mode }, `Setting mode to ${mode}...`);
    }

    /**
     * Handle takeoff command with safety confirmation
     */
    handleTakeoffCommand() {
        if (!this.validateConnection()) return;

        const altitudeInput = document.getElementById('takeoff-altitude');
        const altitude = altitudeInput ? parseFloat(altitudeInput.value) : 10;

        if (altitude < 1 || altitude > 100) {
            alert('Takeoff altitude must be between 1 and 100 meters');
            return;
        }

        const message = `TAKEOFF to ${altitude}m altitude? Ensure area is clear.`;
        if (window.WebGCS.utils.showConfirmation(message)) {
            this.sendCommand('takeoff', { altitude: altitude }, `Taking off to ${altitude}m...`);
        }
    }

    /**
     * Handle emergency stop
     */
    handleEmergencyStop() {
        const message = 'EMERGENCY STOP? This will immediately disarm the drone!';
        if (window.WebGCS.utils.showConfirmation(message)) {
            this.sendCommand('emergency_stop', {}, 'Emergency stop initiated...');
        }
    }

    /**
     * Handle goto waypoint command
     */
    handleGotoWaypoint() {
        if (!this.validateConnection()) return;

        const latInput = document.getElementById('goto-latitude');
        const lonInput = document.getElementById('goto-longitude');
        const altInput = document.getElementById('goto-altitude');

        if (!latInput || !lonInput || !altInput) {
            console.error('Navigation input fields not found');
            return;
        }

        const latitude = parseFloat(latInput.value);
        const longitude = parseFloat(lonInput.value);
        const altitude = parseFloat(altInput.value);

        if (!this.validateCoordinates(latitude, longitude, altitude)) {
            return;
        }

        this.sendCommand('goto_waypoint', {
            latitude: latitude,
            longitude: longitude,
            altitude: altitude
        }, 'Flying to waypoint...');
    }

    /**
     * Handle set home command
     */
    handleSetHome() {
        if (!this.validateConnection()) return;

        if (window.WebGCS.utils.showConfirmation('Set current position as home?')) {
            this.sendCommand('set_home', {}, 'Setting home position...');
        }
    }

    /**
     * Handle gimbal center
     */
    handleGimbalCenter() {
        if (!this.validateConnection()) return;
        this.sendCommand('gimbal_control', { pitch: 0, yaw: 0 }, 'Centering gimbal...');
    }

    /**
     * Handle gimbal down
     */
    handleGimbalDown() {
        if (!this.validateConnection()) return;
        this.sendCommand('gimbal_control', { pitch: -90, yaw: 0 }, 'Pointing gimbal down...');
    }

    /**
     * Validate connection before sending commands
     */
    validateConnection() {
        if (!window.WebGCS.connected) {
            alert('Not connected to server');
            return false;
        }

        if (!window.WebGCS.droneConnected) {
            alert('Drone not connected');
            return false;
        }

        return true;
    }

    /**
     * Validate coordinates
     */
    validateCoordinates(latitude, longitude, altitude) {
        if (isNaN(latitude) || latitude < -90 || latitude > 90) {
            alert('Latitude must be between -90 and 90 degrees');
            return false;
        }

        if (isNaN(longitude) || longitude < -180 || longitude > 180) {
            alert('Longitude must be between -180 and 180 degrees');
            return false;
        }

        if (isNaN(altitude) || altitude < 0 || altitude > 1000) {
            alert('Altitude must be between 0 and 1000 meters');
            return false;
        }

        return true;
    }

    /**
     * Send command with tracking and feedback
     */
    sendCommand(command, params = {}, statusMessage = '') {
        const connectionManager = window.WebGCS.modules.connection;
        if (!connectionManager) {
            console.error('Connection manager not available');
            return;
        }

        const commandId = Date.now().toString();

        // Show status message
        if (statusMessage) {
            this.showStatus(statusMessage);
        }

        // Track pending command
        this.pendingCommands.set(commandId, {
            command: command,
            timestamp: Date.now(),
            timeout: setTimeout(() => {
                this.handleCommandTimeout(commandId);
            }, this.commandTimeout)
        });

        // Send command
        const success = connectionManager.sendCommand(command, {
            ...params,
            command_id: commandId
        });

        if (!success) {
            this.pendingCommands.delete(commandId);
            this.showStatus('Failed to send command', 'error');
        }
    }

    /**
     * Handle command timeout
     */
    handleCommandTimeout(commandId) {
        const command = this.pendingCommands.get(commandId);
        if (command) {
            console.warn(`Command timeout: ${command.command}`);
            this.showStatus(`Command timeout: ${command.command}`, 'error');
            this.pendingCommands.delete(commandId);
        }
    }

    /**
     * Handle command acknowledgment
     */
    handleCommandAck(data) {
        const commandId = data.command_id;
        if (commandId && this.pendingCommands.has(commandId)) {
            const command = this.pendingCommands.get(commandId);
            clearTimeout(command.timeout);
            this.pendingCommands.delete(commandId);

            if (data.success) {
                this.showStatus(`${command.command} successful`, 'success');
            } else {
                this.showStatus(`${command.command} failed: ${data.error || 'Unknown error'}`, 'error');
            }
        }
    }

    /**
     * Show status message
     */
    showStatus(message, type = 'info') {
        const statusElement = document.getElementById('command-status');
        if (statusElement) {
            statusElement.textContent = message;
            statusElement.className = `status ${type}`;

            // Clear after 5 seconds
            setTimeout(() => {
                statusElement.textContent = '';
                statusElement.className = 'status';
            }, 5000);
        }

        console.log(`Status [${type}]: ${message}`);
    }

    /**
     * Setup SocketIO event handlers
     */
    setupSocketEventHandlers() {
        const connectionManager = window.WebGCS.modules.connection;
        if (!connectionManager) {
            console.error('Connection manager not available for event setup');
            return;
        }

        // Handle command acknowledgments
        connectionManager.on('command_acknowledged', (data) => {
            this.handleCommandAck({ 
                command_id: data.command_id || data.command, 
                success: true,
                command: data.command 
            });
        });

        // Handle command errors
        connectionManager.on('command_error', (data) => {
            this.handleCommandAck({ 
                command_id: data.command_id || data.command, 
                success: false, 
                error: data.error,
                command: data.command 
            });
        });

        // Handle connection status changes
        connectionManager.on('drone_connected', () => {
            this.updateButtonStates();
        });

        connectionManager.on('drone_disconnected', () => {
            this.updateButtonStates();
        });

        connectionManager.on('connection_error', (data) => {
            this.showStatus(`Connection error: ${data.message}`, 'error');
        });
    }

    /**
     * Update button states based on drone status
     */
    updateButtonStates() {
        const connected = window.WebGCS.droneConnected;
        const telemetry = window.WebGCS.telemetryData;

        // Update button availability
        const controlButtons = document.querySelectorAll('.flight-control-btn');
        controlButtons.forEach(button => {
            button.disabled = !connected;
        });

        // Update ARM/DISARM button states
        const armBtn = document.getElementById('arm-btn');
        const disarmBtn = document.getElementById('disarm-btn');

        if (armBtn && disarmBtn && telemetry && telemetry.armed !== undefined) {
            if (telemetry.armed) {
                armBtn.disabled = true;
                disarmBtn.disabled = false;
            } else {
                armBtn.disabled = false;
                disarmBtn.disabled = !connected;
            }
        }
    }
}

// Export for use in main.js
window.FlightControls = FlightControls;

/**
 * WebGCS Main JavaScript Module
 * Central coordination and initialization for the web interface.
 */

// Global state management
window.WebGCS = {
    socket: null,
    connected: false,
    droneConnected: false,
    telemetryData: {},
    config: {
        updateInterval: 100, // 10Hz updates
        reconnectInterval: 5000,
        commandTimeout: 5000
    },
    modules: {}
};

/**
 * Initialize the WebGCS application
 */
function initializeWebGCS() {
    console.log('Initializing WebGCS...');

    // Load configuration first
    loadConfiguration();

    // Initialize SocketIO connection
    initializeSocket();

    // Initialize UI components
    initializeUI();

    // Set up periodic tasks
    setupPeriodicTasks();

    console.log('WebGCS initialization complete');
}

/**
 * Initialize SocketIO connection
 */
function initializeSocket() {
    if (typeof window.ConnectionManager !== 'undefined') {
        window.WebGCS.modules.connection = new window.ConnectionManager();
        window.WebGCS.modules.connection.initialize();
    } else {
        console.warn('ConnectionManager not available');
    }
}

/**
 * Load application configuration
 */
async function loadConfiguration() {
    try {
        const response = await fetch('/api/status');
        if (response.ok) {
            const data = await response.json();
            window.WebGCS.config.droneHost = data.config?.drone_host || '192.168.193.235';
            window.WebGCS.config.dronePort = data.config?.drone_port || 5678;
        }
    } catch (error) {
        console.warn('Could not load configuration:', error);
    }
}

/**
 * Initialize UI components
 */
function initializeUI() {
    // Initialize telemetry display
    if (typeof window.TelemetryDisplay !== 'undefined') {
        window.WebGCS.modules.telemetry = new window.TelemetryDisplay();
        window.WebGCS.modules.telemetry.initialize();
    }

    // Initialize flight controls
    if (typeof window.FlightControls !== 'undefined') {
        window.WebGCS.modules.controls = new window.FlightControls();
        window.WebGCS.modules.controls.initialize();
    }

    // Initialize PFD
    if (typeof window.PrimaryFlightDisplay !== 'undefined') {
        window.WebGCS.modules.pfd = new window.PrimaryFlightDisplay();
        window.WebGCS.modules.pfd.initialize();
    }

    // Initialize validation
    if (typeof window.InputValidation !== 'undefined') {
        window.WebGCS.modules.validation = new window.InputValidation();
        window.WebGCS.modules.validation.initialize();
    }

    console.log('UI components initialized');
}

/**
 * Setup periodic tasks
 */
function setupPeriodicTasks() {
    // Connection status check every 5 seconds
    setInterval(() => {
        updateConnectionStatus();
    }, 5000);
}

/**
 * Update connection status indicator
 */
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    if (!statusElement) return;

    const socket = window.WebGCS.socket;
    const connected = socket && socket.connected;
    const droneConnected = window.WebGCS.droneConnected;

    let status = 'Disconnected';
    let className = 'disconnected';

    if (connected && droneConnected) {
        status = 'Connected to Drone';
        className = 'connected';
    } else if (connected) {
        status = 'Server Connected';
        className = 'partial';
    }

    statusElement.textContent = status;
    statusElement.className = `connection-indicator ${className}`;

    // FIX: Update connection panel status
    const panelStatusElement = document.getElementById('connection-status-text');
    if (panelStatusElement) {
        panelStatusElement.textContent = droneConnected ? 'Connected' : 'Disconnected';
        panelStatusElement.className = droneConnected ? 'status-connected' : 'status-disconnected';
    }

    // FIX: Update heartbeat timestamps when connected
    if (droneConnected && window.WebGCS.telemetryData && window.WebGCS.telemetryData.timestamp) {
        const lastHeartbeat = document.getElementById('last-heartbeat');
        const telemetryHeartbeat = document.getElementById('telemetry-last-heartbeat');
        const heartbeatTime = new Date(window.WebGCS.telemetryData.timestamp * 1000).toLocaleTimeString();

        if (lastHeartbeat) lastHeartbeat.textContent = heartbeatTime;
        if (telemetryHeartbeat) telemetryHeartbeat.textContent = heartbeatTime;
    }
}

/**
 * Global error handler
 */
window.addEventListener('error', (event) => {
    console.error('WebGCS Error:', event.error);
});

/**
 * Global utility functions
 */
window.WebGCS.utils = {
    formatNumber: (value, decimals = 1) => {
        return parseFloat(value).toFixed(decimals);
    },

    formatTime: (timestamp) => {
        return new Date(timestamp).toLocaleTimeString();
    },

    showConfirmation: (message) => {
        return confirm(message);
    }
};

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initializeWebGCS);

"""
WebGCS SocketIO Event Handlers
Real-time communication between web interface and backend systems.
"""

from flask_socketio import SocketIO, emit, disconnect
from flask import request
import logging
from typing import Dict, Any

logger = logging.getLogger('webgcs')


def register_socketio_handlers(socketio: SocketIO) -> None:
    """
    Register all SocketIO event handlers.

    Args:
        socketio: SocketIO instance to register handlers with
    """

    @socketio.on('connect')
    def handle_connect(auth):
        """Handle client connection."""
        client_id = request.sid
        logger.info(f"Client connected: {client_id}")

        # Send initial connection confirmation
        emit('connection_status', {
            'status': 'connected',
            'client_id': client_id,
            'message': 'WebGCS connection established'
        })

        # FIX: Send current drone status and telemetry
        from flask import current_app
        mavlink_service = getattr(current_app, 'mavlink_service', None)
        if mavlink_service:
            status = mavlink_service.get_status()

            # Send drone connection status
            is_connected = status.get('mavlink_connected', False)
            emit('drone_connected' if is_connected else 'drone_disconnected', {
                'status': 'connected' if is_connected else 'disconnected',
                'timestamp': status.get('last_heartbeat').isoformat() if status.get('last_heartbeat') else None
            })

            emit('system_status', {
                'mavlink_connected': is_connected,
                'drone_armed': status.get('armed_status', False),
                'flight_mode': status.get('flight_mode', 'UNKNOWN'),
                'last_heartbeat': status.get('last_heartbeat').isoformat() if status.get('last_heartbeat') else None
            })

            # FIX: Send current telemetry data if available
            telemetry = mavlink_service.message_processor.get_telemetry_snapshot()
            if telemetry:
                # Add timestamp for heartbeat display
                telemetry['timestamp'] = status.get('last_heartbeat').isoformat() if status.get('last_heartbeat') else None
                emit('telemetry_update', telemetry)
        else:
            emit('system_status', {
                'mavlink_connected': False,
                'drone_armed': False,
                'flight_mode': 'UNKNOWN',
                'last_heartbeat': None
            })


    @socketio.on('disconnect')
    def handle_disconnect():
        """Handle client disconnection."""
        client_id = request.sid
        logger.info(f"Client disconnected: {client_id}")


    @socketio.on('request_telemetry')
    def handle_telemetry_request(data: Dict[str, Any]):
        """
        Handle telemetry data requests.

        Args:
            data: Request parameters including update rate
        """
        try:
            client_id = request.sid
            update_rate = data.get('rate_hz', 4)

            logger.info(f"Telemetry requested by {client_id} at {update_rate}Hz")

            # Acknowledge telemetry stream request
            # The MAVLink service already streams telemetry automatically
            emit('telemetry_stream_started', {
                'rate_hz': update_rate,
                'status': 'acknowledged'
            })

        except Exception as e:
            logger.error(f"Error handling telemetry request: {e}")
            emit('error', {'message': 'Failed to start telemetry stream'})


    @socketio.on('send_command')
    def handle_command(data: Dict[str, Any]):
        """
        Handle MAVLink command requests.

        Args:
            data: Command parameters including command type and parameters
        """
        try:
            client_id = request.sid
            command_type = data.get('command')
            parameters = data.get('parameters', {})

            logger.info(f"Command received from {client_id}: {command_type}")

            # Execute command via MAVLink service
            from flask import current_app
            mavlink_service = getattr(current_app, 'mavlink_service', None)

            if not mavlink_service:
                emit('command_error', {
                    'command': command_type,
                    'error': 'MAVLink service not available'
                })
                return

            success = False
            error_msg = None

            try:
                # Route command to appropriate handler
                if command_type == 'connect_drone':
                    success = mavlink_service.connect_to_drone()
                    if success:
                        emit('drone_connected', {
                            'status': 'connected',
                            'message': 'Drone connected successfully'
                        })
                    else:
                        emit('connection_error', {
                            'status': 'failed',
                            'message': 'Failed to connect to drone'
                        })
                    return  # Early return for connection commands

                elif command_type == 'disconnect_drone':
                    success = mavlink_service.disconnect_from_drone()
                    emit('drone_disconnected', {
                        'status': 'disconnected',
                        'message': 'Drone disconnected'
                    })
                    return  # Early return for connection commands

                elif command_type == 'arm':
                    success = mavlink_service.arm_vehicle()
                elif command_type == 'disarm':
                    force = parameters.get('force', False)
                    success = mavlink_service.disarm_vehicle(force)
                elif command_type == 'takeoff':
                    altitude = parameters.get('altitude', 10.0)
                    success = mavlink_service.takeoff(altitude)
                elif command_type == 'land':
                    success = mavlink_service.land()
                elif command_type == 'rtl':
                    success = mavlink_service.return_to_launch()
                elif command_type == 'set_mode':
                    mode = parameters.get('mode', 'GUIDED')
                    success = mavlink_service.set_mode(mode)
                elif command_type == 'goto_waypoint':
                    latitude = parameters.get('latitude')
                    longitude = parameters.get('longitude')
                    altitude = parameters.get('altitude', 10.0)
                    if latitude is not None and longitude is not None:
                        success = mavlink_service.goto_waypoint(latitude, longitude, altitude)
                    else:
                        error_msg = "goto_waypoint requires latitude and longitude"
                elif command_type == 'set_home':
                    success = mavlink_service.set_home()
                elif command_type == 'emergency_stop':
                    success = mavlink_service.emergency_stop()
                elif command_type == 'gimbal_control':
                    pitch = parameters.get('pitch', 0)
                    yaw = parameters.get('yaw', 0)
                    success = mavlink_service.gimbal_control(pitch, yaw)
                else:
                    error_msg = f"Unknown command: {command_type}"

                if success:
                    emit('command_acknowledged', {
                        'command': command_type,
                        'status': 'success',
                        'parameters': parameters
                    })
                elif error_msg:
                    emit('command_error', {
                        'command': command_type,
                        'error': error_msg
                    })
                else:
                    emit('command_error', {
                        'command': command_type,
                        'error': 'Command failed or timed out'
                    })

            except Exception as e:
                logger.error(f"Error executing command {command_type}: {e}")
                emit('command_error', {
                    'command': command_type,
                    'error': f'Exception: {str(e)}'
                })

        except Exception as e:
            logger.error(f"Error handling command: {e}")
            emit('command_error', {
                'command': data.get('command'),
                'error': 'Failed to process command'
            })


    @socketio.on('request_connection_status')
    def handle_connection_status_request():
        """Handle request for current connection status."""
        try:
            # Get connection status from MAVLink service
            from flask import current_app
            mavlink_service = getattr(current_app, 'mavlink_service', None)

            if mavlink_service:
                status = mavlink_service.get_status()
                emit('connection_status_update', {
                    'mavlink_connected': status.get('mavlink_connected', False),
                    'connection_state': status.get('connection_state', 'disconnected'),
                    'drone_endpoint': status.get('drone_endpoint', 'unknown'),
                    'last_heartbeat': status.get('last_heartbeat').isoformat() if status.get('last_heartbeat') else None,
                    'flight_mode': status.get('flight_mode', 'UNKNOWN'),
                    'armed_status': status.get('armed_status', False)
                })
            else:
                emit('connection_status_update', {
                    'mavlink_connected': False,
                    'drone_endpoint': 'unknown',
                    'last_heartbeat': None,
                    'connection_time': None
                })

        except Exception as e:
            logger.error(f"Error getting connection status: {e}")
            emit('error', {'message': 'Failed to get connection status'})


    @socketio.on('error')
    def handle_error(data):
        """Handle SocketIO errors."""
        client_id = request.sid
        logger.error(f"SocketIO error from {client_id}: {data}")


def emit_telemetry_update(socketio: SocketIO, telemetry_data: Dict[str, Any]) -> None:
    """
    Broadcast telemetry update to all connected clients.

    Args:
        socketio: SocketIO instance
        telemetry_data: Telemetry data to broadcast
    """
    try:
        socketio.emit('telemetry_update', telemetry_data)
    except Exception as e:
        logger.error(f"Error emitting telemetry update: {e}")


def emit_command_response(socketio: SocketIO, command_id: str, response_data: Dict[str, Any]) -> None:
    """
    Emit command response to specific client.

    Args:
        socketio: SocketIO instance
        command_id: ID of the command being responded to
        response_data: Response data to send
    """
    try:
        socketio.emit('command_response', {
            'command_id': command_id,
            'response': response_data
        })
    except Exception as e:
        logger.error(f"Error emitting command response: {e}")

