      return {
        socketConnected: !!window.WebGCS?.connected,
        droneConnected: !!window.WebGCS?.droneConnected,
        buttonText: document.getElementById('connect-drone-btn')?.textContent
      };
    });

    console.log(`📊 Final Status:`, finalStatus);

    // Results summary
